WITH filtered AS (SELECT id, customer_id, store_id, order_date, channel, discount, shipping_fee, CASE WHEN shipping_fee >= 35 THEN 'High' WHEN shipping_fee >= 7 THEN 'Medium' ELSE 'Low' END AS shipping_fee_level FROM orders WHERE order_date >= TO_DATE('2023-05-23') AND customer_id IS NOT NULL), metrics AS (SELECT id, customer_id, order_date, channel, shipping_fee, NTILE(4) OVER (PARTITION BY customer_id ORDER BY discount DESC, id) AS discount_bucket, CORR(discount, shipping_fee) OVER (PARTITION BY channel) AS corr_discount_shipping_fee, RANK() OVER (ORDER BY discount DESC) AS discount_rank FROM filtered), latest_match AS (SELECT s.*, top1.payment_status, top1.payment_amount FROM metrics s LEFT JOIN LATERAL (SELECT c.status AS payment_status, c.amount AS payment_amount FROM payments c WHERE c.order_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) top1 ON TRUE), cleaned AS (SELECT *, CAST(discount_bucket AS DOUBLE) AS discount_bucket_num FROM latest_match WHERE customer_id IS NOT NULL), latest_match_orders AS (SELECT s.*, x.order_item_quantity FROM cleaned s LEFT JOIN LATERAL (SELECT c.quantity AS order_item_quantity FROM order_items c WHERE c.order_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) x ON TRUE), eligible AS (SELECT s.* FROM latest_match_orders s WHERE NOT EXISTS (SELECT 1 FROM order_items x WHERE x.order_id = s.id AND x.order_id IN (8, 25, 27))), matched AS (SELECT s.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM eligible s INNER JOIN promotions pr ON s.channel <=> pr.channel AND s.order_date >= pr.starts_on AND s.order_date <= DATE_ADD(pr.ends_on, 7)) SELECT id, customer_id, order_date, channel, shipping_fee, discount_bucket, payment_status, payment_amount, discount_bucket_num FROM matched ORDER BY customer_id DESC NULLS LAST;
